using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace Flagman;
public static class WorkflowService
{
 public static string Scope(Actor a,string operation)=>"wf:"+a.UserId+":"+operation;
 static T Once<T>(State s,Actor a,string op,string key,object input,Func<T> action){var previous=s.EventActorId;s.EventActorId=a.UserId;try{return Inventory.Once(s,Scope(a,op),key,input,action);}finally{s.EventActorId=previous;}}
 static void Pending(string status,int version,int expected){Inventory.Require(status=="submitted"&&version==expected,"Заявка уже обработана или версия устарела",409);}
 static void Reason(decimal before,decimal after,string? reason){Inventory.Require(after>=0&&after<=before,"Количество превышает заявленное");Inventory.Require(after==before||!string.IsNullOrWhiteSpace(reason)&&reason.Length<=500,"Укажите причину уменьшения/отказа");}
 static void Lines<T>(List<T>? lines,List<string> expected,Func<T,string> id){Inventory.Require(lines is {Count:>0 and <=100}&&lines.Count==expected.Count&&lines.Select(id).Distinct().Count()==expected.Count&&lines.All(x=>expected.Contains(id(x))),"Обработайте каждую строку ровно один раз");}
 static DeliveryRequestLine Normalize(State s,DeliveryLine line,DateTimeOffset now,string? procurementLineId=null){var scratch=new State{Products=s.Products,Settings=s.Settings};Inventory.Deliver(scratch,new("validation",[line]),"validation",now);var b=scratch.Batches.Single();return new(Inventory.Id(),line.ProductId,line.Quantity,line.Unit,b.ExpiresAt,line.UnitCost,line.Currency,procurementLineId,b.ManufacturedAt,b.ShelfLifeHours);}
 public static ProcurementRequest CreateProcurement(State s,ProcurementRequestInput input,Actor actor,string key,DateTimeOffset now){AccessService.RequireRole(actor,"manager");return Once(s,actor,"procurement",key,input,()=>{Inventory.Require(s.Users.Any(u=>u.Id==input.SupplierId&&u.Role=="supplier"&&u.Active),"Выберите активного поставщика");Inventory.Require(input.Items is {Count:>0 and <=100},"Нужны строки закупки");Inventory.Require(input.Items.Select(x=>x.Id).Distinct().Count()==input.Items.Count&&input.Items.All(x=>!string.IsNullOrWhiteSpace(x.Id)),"ID строк должны быть уникальны");Inventory.Require(input.Comment==null||input.Comment.Length<=500,"Комментарий до 500 символов");foreach(var l in input.Items){var p=Inventory.Product(s,l.ProductId);Inventory.Require(!p.Archived,"Продукт архивирован");Inventory.ConvertQuantity(l.Quantity,l.Unit,p.Unit);}var r=new ProcurementRequest(Inventory.Id(),actor.UserId,input.SupplierId,input.Items,input.DesiredAt,input.Comment,now);s.ProcurementRequests.Add(r);AccessService.Audit(s,actor,"procurement.submitted",r.Id,now);return r;});}
 public static ProcurementResponseResult RespondProcurement(State s,string id,ProcurementResponseInput input,Actor actor,string key,DateTimeOffset now){AccessService.RequireRole(actor,"supplier");var current=s.ProcurementRequests.Find(x=>x.Id==id)??throw new DomainException("Заявка не найдена",404);AccessService.RequireOwner(actor,current.SupplierId);return Once(s,actor,"procurement-response",key,new{id,input},()=>{Pending(current.Status,current.Version,input.ExpectedVersion);Lines(input.Items,current.Items.Select(x=>x.Id).ToList(),x=>x.LineId);var deliveryLines=new List<DeliveryRequestLine>();foreach(var l in input.Items){var original=current.Items.Single(x=>x.Id==l.LineId);Reason(original.Quantity,l.ConfirmedQuantity,l.Reason);if(l.ConfirmedQuantity>0)deliveryLines.Add(Normalize(s,new(original.ProductId,l.ConfirmedQuantity,original.Unit,l.ExpiresAt,l.ShelfLifeHours,l.ManufacturedAt,l.ExpiryDate,l.UnitCost,l.Currency),now,l.LineId));}var delivery=deliveryLines.Count==0?null:new DeliveryRequest(Inventory.Id(),actor.UserId,"Закупка "+id[..8],deliveryLines,now,id);if(delivery!=null)s.DeliveryRequests.Add(delivery);var status=delivery==null?"rejected":input.Items.All(l=>l.ConfirmedQuantity==current.Items.Single(x=>x.Id==l.LineId).Quantity)?"accepted":"partially_accepted";var updated=current with{Status=status,Version=current.Version+1,Response=input.Items,DeliveryRequestId=delivery?.Id};s.ProcurementRequests[s.ProcurementRequests.IndexOf(current)]=updated;AccessService.Audit(s,actor,"procurement.responded",id,now);return new ProcurementResponseResult(updated,delivery?.Id);});}
 public static ProcurementRequest CancelProcurement(State s,string id,VersionInput input,Actor actor,string key,DateTimeOffset now){AccessService.RequireRole(actor,"manager");return Once(s,actor,"procurement-cancel",key,new{id,input},()=>{var r=s.ProcurementRequests.Find(x=>x.Id==id)??throw new DomainException("Заявка не найдена",404);Pending(r.Status,r.Version,input.ExpectedVersion);var updated=r with{Status="cancelled",Version=r.Version+1};s.ProcurementRequests[s.ProcurementRequests.IndexOf(r)]=updated;AccessService.Audit(s,actor,"procurement.cancelled",id,now);return updated;});}
 public static DeliveryRequest SubmitDelivery(State s,DeliveryRequestInput input,Actor actor,string key,DateTimeOffset now){AccessService.RequireRole(actor,"supplier","manager");return Once(s,actor,"delivery",key,input,()=>{Inventory.Require(input.Number is {Length:>0 and <=100}&&input.Items is {Count:>0 and <=100},"Нужны номер и состав поставки");var lines=input.Items.Select(x=>Normalize(s,x,now)).ToList();var r=new DeliveryRequest(Inventory.Id(),actor.UserId,input.Number,lines,now);s.DeliveryRequests.Add(r);AccessService.Audit(s,actor,"delivery-request.submitted",r.Id,now);return r;});}
 public static DeliveryRequest AcceptDelivery(State s,string id,DeliveryAcceptanceInput input,Actor actor,string key,DateTimeOffset now){AccessService.RequireRole(actor,"manager");return Once(s,actor,"delivery-acceptance",key,new{id,input},()=>{var r=s.DeliveryRequests.Find(x=>x.Id==id)??throw new DomainException("Заявка не найдена",404);Pending(r.Status,r.Version,input.ExpectedVersion);Lines(input.Items,r.Items.Select(x=>x.Id).ToList(),x=>x.LineId);var accepted=new List<DeliveryLine>();foreach(var l in input.Items){var original=r.Items.Single(x=>x.Id==l.LineId);Reason(original.Quantity,l.AcceptedQuantity,l.Reason);if(l.AcceptedQuantity>0){var expiry=l.VerifiedExpiresAt??original.ExpiresAt;Inventory.Require(expiry>now,"Просроченный товар нельзя принять");accepted.Add(new(original.ProductId,l.AcceptedQuantity,original.Unit,expiry,ShelfLifeHours:original.ShelfLifeHours,ManufacturedAt:original.ManufacturedAt,UnitCost:original.UnitCost,Currency:original.Currency));}}var delivery=accepted.Count==0?null:Inventory.Deliver(s,new(r.Number,accepted),"wf-receipt-"+r.Id,now);var status=delivery==null?"rejected":input.Items.All(x=>x.AcceptedQuantity==r.Items.Single(l=>l.Id==x.LineId).Quantity)?"accepted":"partially_accepted";var updated=r with{Status=status,Version=r.Version+1,Acceptance=input.Items,DeliveryId=delivery?.Id,DecisionActorId=actor.UserId,DecidedAt=now};s.DeliveryRequests[s.DeliveryRequests.IndexOf(r)]=updated;AccessService.Audit(s,actor,"delivery-request."+updated.Status,id,now);return updated;});}
 static string Fingerprint(State s,List<OrderItem> items){var dishes=items.Select(x=>s.Dishes.Find(d=>d.Id==x.DishId)??throw new DomainException("Блюдо не найдено")).OrderBy(x=>x.Id).ToList();return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(dishes,Store.Json))));}
 public static int ReserveLegacyOrders(State s,DateTimeOffset now)
 {
  var count=0;
  foreach(var r in s.OrderRequests.Where(r=>r.Status=="submitted"&&r.Reservations==null).OrderBy(r=>r.CreatedAt).ThenBy(r=>r.Id).ToList()){
   var needs=new Dictionary<string,decimal>();
   foreach(var item in r.Items)foreach(var ingredient in s.Dishes.Find(d=>d.Id==item.DishId)?.Ingredients??[])
    needs[ingredient.ProductId]=needs.GetValueOrDefault(ingredient.ProductId)+ingredient.Quantity*item.Portions;
   var reservations=new List<BatchReservation>();
   // Older versions allowed overbooking. Protect what remains, without altering
   // the original order or inventing stock; the cook resolves any shortage.
   foreach(var need in needs){var remaining=need.Value;foreach(var b in Inventory.Usable(s,need.Key,now)){
    var quantity=Math.Min(remaining,b.RemainingQuantity);reservations.Add(new(b.Id,quantity));remaining-=quantity;if(remaining==0)break;
   }}
   s.OrderRequests[s.OrderRequests.IndexOf(r)]=r with{Reservations=reservations,IngredientProducts=needs.Keys.Select(id=>new RejectionProduct(id,Inventory.Product(s,id).Name)).ToList()};
   AccessService.Audit(s,new("system-reservations","manager"),"order-request.reserved",r.Id,now);count++;
  }
  return count;
 }
 public static OrderRequest SubmitOrder(State s,OrderRequestInput input,Actor actor,string key,DateTimeOffset now,bool validateAvailability=true){AccessService.RequireRole(actor,"waiter","manager");return Once(s,actor,"order",key,input,()=>{ReserveLegacyOrders(s,now);Inventory.Require(input.Items is {Count:>0 and <=100}&&input.Items.All(x=>x.Portions is >0 and <=10000)&&input.Items.Select(x=>x.DishId).Distinct().Count()==input.Items.Count,"Укажите блюда и порции без повторов");foreach(var l in input.Items){var d=s.Dishes.Find(x=>x.Id==l.DishId)??throw new DomainException("Блюдо не найдено");Inventory.Require(!d.Archived&&d.Ingredients.Count>0,"Блюдо недоступно");}var needs=new Dictionary<string,decimal>();foreach(var item in input.Items)foreach(var ingredient in s.Dishes.Single(d=>d.Id==item.DishId).Ingredients)needs[ingredient.ProductId]=needs.GetValueOrDefault(ingredient.ProductId)+ingredient.Quantity*item.Portions;
 var missing=Inventory.Missing(s,needs,input.Items.Select(i=>i.DishId),now);
 Inventory.Require(!validateAvailability||missing.Count==0,"Недостаточно свободных продуктов: остаток уже зарезервирован или недоступен",409);
 var reservations=new List<BatchReservation>();if(missing.Count==0)foreach(var need in needs){var remaining=need.Value;foreach(var batch in Inventory.Usable(s,need.Key,now)){var quantity=Math.Min(remaining,batch.RemainingQuantity);reservations.Add(new(batch.Id,quantity));remaining-=quantity;if(remaining==0)break;}}
 var r=new OrderRequest(Inventory.Id(),actor.UserId,input.Items,Fingerprint(s,input.Items),now,Status:missing.Count==0?"submitted":"rejected",Reason:missing.Count==0?null:"Недостаточно свободных продуктов",Shortages:missing,Reservations:reservations,IngredientProducts:needs.Keys.Select(id=>new RejectionProduct(id,Inventory.Product(s,id).Name)).ToList());s.OrderRequests.Add(r);AccessService.Audit(s,actor,"order-request.submitted",r.Id,now);return r;});}
 public static OrderRequest DecideOrder(State s,string id,OrderDecisionInput input,Actor actor,string key,DateTimeOffset now){AccessService.RequireRole(actor,"cook");return Once(s,actor,"order-decision",key,new{id,input},()=>{ReserveLegacyOrders(s,now);var r=s.OrderRequests.Find(x=>x.Id==id)??throw new DomainException("Заявка не найдена",404);Pending(r.Status,r.Version,input.ExpectedVersion);Inventory.Require(input.Decision is "accept" or "reject","Решение: accept или reject");Order? order=null;OrderRejection? rejection=null;if(input.Decision=="reject")rejection=OrderRejections.Validate(s,r,input);else{Inventory.Require(r.RecipeFingerprint==Fingerprint(s,r.Items)&&r.Items.All(i=>s.Dishes.Any(d=>d.Id==i.DishId&&!d.Archived)),"Рецептура изменилась; отклоните заявку и создайте новую",409);s.OrderRequests[s.OrderRequests.IndexOf(r)]=r with{Status="preparing-completion"};order=Inventory.PlaceOrder(s,new(r.Items),"wf-order-"+r.Id,now);}var updated=r with{Status=order?.Status=="accepted"?"ready":"rejected",Version=r.Version+1,OrderId=order?.Id,Reason=rejection!=null?OrderRejections.Describe(rejection):(order?.Status=="rejected"?"Недостаточно ингредиентов":null),Rejection=rejection,Shortages=order?.Shortages??[],DecisionActorId=actor.UserId,DecidedAt=now};s.OrderRequests[s.OrderRequests.FindIndex(x=>x.Id==r.Id)]=updated;AccessService.Audit(s,actor,"order-request."+updated.Status,id,now);return updated;});}
 public static OrderRequest ServeOrder(State s,string id,VersionInput input,Actor actor,string key,DateTimeOffset now)
 {
  AccessService.RequireRole(actor,"waiter","manager");
  var r=s.OrderRequests.Find(x=>x.Id==id)??throw new DomainException("Заказ не найден",404);
  Inventory.Require(actor.Role=="admin"||actor.UserId==r.AuthorId,"Заказ не найден",404);
  return Once(s,actor,"order-serve",key,new{id,input},()=>{
   Inventory.Require(r.Status=="ready"&&r.Version==input.ExpectedVersion,"Заказ ещё не готов, уже выдан или версия устарела",409);
   var updated=r with{Status="served",Version=r.Version+1,ServedById=actor.UserId,ServedAt=now};
   s.OrderRequests[s.OrderRequests.IndexOf(r)]=updated;
   AccessService.Audit(s,actor,"order-request.served",id,now);return updated;
  });
 }
}
